-- Dumping data for table blog_management_system.blogs: ~4 rows (approximately)
INSERT INTO `blogs` (`id`, `title`, `slug`, `short_description`, `content`, `category_id`, `image`, `published_at`, `created_at`, `updated_at`) VALUES
	(1, 'SSC CGL Recruitment 2026', 'ssc-cgl-recruitment-2026', 'The SSC CGL Recruitment 2026 notification has been released for multiple government vacancies across India. Candidates can apply online, check eligibility criteria, and prepare for the upcoming examination process.', '<h2>SSC CGL Recruitment 2026</h2><div>The Staff Selection Commission (SSC) has officially announced the SSC CGL Recruitment 2026 for various Group B and Group C government posts. Thousands of vacancies are expected across different ministries and departments.</div><div><b><br></b></div><div><b>Eligibility Criteria</b></div><div><ul><li>Candidates must have completed graduation from a recognized university.</li><li>Applicants should meet the required age criteria mentioned in the notification.</li><li>Both freshers and experienced candidates can apply.</li></ul></div><div><b>Selection Process</b></div><div>The selection process includes Tier 1, Tier 2 examinations followed by document verification. Candidates are advised to prepare thoroughly for quantitative aptitude, reasoning, English, and general awareness sections.</div><div><br></div><div><b>Important Dates</b></div><div><ul><li>Application Start Date: June 2026</li><li>Last Date to Apply: July 2026</li><li>Exam Date: September 2026</li></ul></div><div>Interested candidates should regularly visit the official SSC website for latest updates regarding admit cards, syllabus, and examination schedules.</div>', 1, '1778175546.png', '2026-05-07', '2026-05-07 12:09:06', '2026-05-07 12:09:06'),
	(2, 'AI Tools Every College Student Should Learn in 2026', 'ai-tools-for-college-students-2026', 'Artificial Intelligence tools are transforming the way students study, write code, take notes, and prepare for placements. Here are some useful AI tools every college student should explore in 2026.', '<div><b>Introduction</b></div><div>Artificial Intelligence has become an important part of student life. From coding assistance to note-making and interview preparation,AI tools help students save time and improve productivity.</div><div><br></div><div><b>1. ChatGPT</b></div><div>ChatGPT is useful for learning concepts, debugging code, generating ideas, writing reports, and preparing for interviews. Students can also use it for creating study plans and summaries.</div><div><b>2. GitHub Copilot</b></div><div>GitHub Copilot helps developers by suggesting code in real time. It improves coding speed and helps beginners understand syntax and logic.</div><div><b>3. Perplexity AI</b></div><div>Perplexity AI provides research-based answers with sources. It is especially useful for assignments, presentations, and technical learning.</div><div><b>4. Canva AI</b></div><div>Canva AI allows students to create presentations, posters, social media designs, and resumes easily using AI-assisted templates.</div><div><br></div><div><b>Conclusion</b></div><div>AI tools are becoming essential for modern students.Learning how to use these tools effectively can improve productivity,creativity, and career opportunities.</div>', 1, '1778177288.png', '2026-05-07', '2026-05-07 12:38:08', '2026-05-09 10:51:21'),
	(3, 'Top Web Development Trends in 2026', 'top-web-development-trends-2026', 'Web development technologies are evolving rapidly in 2026 with AI integration, faster frameworks, and improved user experiences becoming the industry standard.', '<div class="" data-turn-id-container="1b796d5f-01b8-4761-bab1-bcb411c014ca" data-is-intersecting="true"><div class="relative w-full overflow-visible"><section class="text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-(--header-height)" dir="auto" data-turn-id="1b796d5f-01b8-4761-bab1-bcb411c014ca" data-turn-id-container="1b796d5f-01b8-4761-bab1-bcb411c014ca" data-testid="conversation-turn-253" data-scroll-anchor="false" data-turn="user"><div class="text-base my-auto mx-auto pt-12 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)"><div class="[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col"><div class="flex max-w-full flex-col gap-4 grow"><div data-message-author-role="user" data-message-id="1b796d5f-01b8-4761-bab1-bcb411c014ca" dir="auto" class="min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1"><div class="flex w-full flex-col gap-1 empty:hidden items-end rtl:items-start"><div class="flex flex-col w-fit max-w-(--user-chat-width,70%) items-start self-end rtl:items-end rtl:self-start"><div class="user-message-bubble-color corner-superellipse/0.98 relative min-w-0 overflow-hidden rounded-[22px] px-4 py-2.5 leading-6 w-full"><div class="A_HxFq_root" data-testid="collapsible-user-message-root"><div id="_r_1u8_" data-testid="collapsible-user-message-content" class="A_HxFq_content"><h2><strong data-start="0" data-end="38">Top Web Development Trends in 2026</strong></h2></div></div></div></div></div></div></div></div></div></section></div></div><div class="" data-turn-id-container="request-69fc91a1-464c-83e8-ae3e-b4e708677fb9-34" data-is-intersecting="true"><div class="relative w-full overflow-visible"><section class="text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" data-turn-id="request-69fc91a1-464c-83e8-ae3e-b4e708677fb9-34" data-turn-id-container="request-69fc91a1-464c-83e8-ae3e-b4e708677fb9-34" data-testid="conversation-turn-254" data-scroll-anchor="false" data-turn="assistant"><div class="text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)"><div class="[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn"><div class="flex max-w-full flex-col gap-4 grow"><div data-message-author-role="assistant" data-message-id="a0a34cae-77bb-45e0-be17-6eaf67d60b10" dir="auto" data-message-model-slug="gpt-5-5" class="min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1" data-turn-start-message="true" tabindex="0"><div class="flex w-full flex-col gap-1 empty:hidden"><div class="markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling">\r\n<p data-start="40" data-end="196">Web development continues to evolve with new frameworks, tools, and technologies improving performance and user experience across websites and applications.</p>\r\n<p data-start="198" data-end="357"><strong data-start="198" data-end="224">1. AI-Powered Websites</strong><br data-start="224" data-end="227">\r\nArtificial Intelligence is being integrated into websites for chatbots, recommendations, automation, and personalized experiences.</p>\r\n<p data-start="359" data-end="535"><strong data-start="359" data-end="386">2. Progressive Web Apps</strong><br data-start="386" data-end="389">\r\nProgressive Web Apps (PWAs) provide app-like experiences directly through browsers while maintaining fast loading speeds and offline capabilities.</p>\r\n<p data-start="537" data-end="710"><strong data-start="537" data-end="570">3. Faster Frontend Frameworks</strong><br data-start="570" data-end="573">\r\nModern frameworks such as React, Vue, and Next.js continue to dominate frontend development because of their performance and scalability.</p>\r\n<p data-start="712" data-end="871"><strong data-start="712" data-end="738">4. Cybersecurity Focus</strong><br data-start="738" data-end="741">\r\nDevelopers are implementing stronger authentication systems and security practices to protect user data and prevent cyber attacks.</p>\r\n<p data-start="873" data-end="998" data-is-last-node="" data-is-only-node=""><strong data-start="873" data-end="887">Conclusion</strong><br data-start="887" data-end="890">\r\nThe future of web development is focused on speed, security, responsiveness, and AI-driven user experiences.</p></div></div></div></div></div></div></section></div></div>', 5, '1778344750.png', '2026-05-09', '2026-05-09 11:02:27', '2026-05-09 11:09:10'),
	(4, 'Best Programming Languages for Beginners in 2026', 'best-programming-languages-for-beginners-2026', 'Choosing the right programming language is important for beginners starting their coding journey. Here are some beginner-friendly programming languages to learn in 2026.', '<div class="" data-turn-id-container="request-69fc91a1-464c-83e8-ae3e-b4e708677fb9-36" data-is-intersecting="true"><div class="relative w-full overflow-visible"><section class="text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" data-turn-id="request-69fc91a1-464c-83e8-ae3e-b4e708677fb9-36" data-turn-id-container="request-69fc91a1-464c-83e8-ae3e-b4e708677fb9-36" data-testid="conversation-turn-258" data-scroll-anchor="false" data-turn="assistant"><div class="text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)"><div class="[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn"><div class="flex max-w-full flex-col gap-4 grow"><div data-message-author-role="assistant" data-message-id="17c15c58-8d5d-4330-be08-14bba923f3b0" dir="auto" data-message-model-slug="gpt-5-5" class="min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1" data-turn-start-message="true" tabindex="0"><div class="flex w-full flex-col gap-1 empty:hidden"><div class="markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling"><h2><strong data-start="0" data-end="52">Best Programming Languages for Beginners in 2026</strong></h2><h2><span style="font-size: 16px;">Programming has become one of the most valuable skills in the modern technology industry. Beginners should start with languages that are simple, practical, and widely used.</span></h2>\r\n<p data-start="228" data-end="356"><strong data-start="228" data-end="241">1. Python</strong><br data-start="241" data-end="244">\r\nPython is one of the easiest programming languages to learn because of its simple syntax and powerful libraries.</p>\r\n<p data-start="358" data-end="492"><strong data-start="358" data-end="375">2. JavaScript</strong><br data-start="375" data-end="378">\r\nJavaScript is essential for web development and allows developers to create interactive websites and applications.</p>\r\n<p data-start="494" data-end="662"><strong data-start="494" data-end="505">3. Java</strong><br data-start="505" data-end="508">\r\nJava is widely used in enterprise software, Android development, and academic learning. It helps students understand object-oriented programming concepts.</p>\r\n<p data-start="664" data-end="761"><strong data-start="664" data-end="674">4. C++</strong><br data-start="674" data-end="677">\r\nC++ is useful for learning data structures, algorithms, and competitive programming.</p>\r\n<p data-start="763" data-end="936" data-is-last-node="" data-is-only-node=""><strong data-start="763" data-end="777">Conclusion</strong><br data-start="777" data-end="780">\r\nSelecting the right programming language depends on career goals, but starting with beginner-friendly languages can make learning easier and more enjoyable.</p></div></div></div></div><div class="z-0 flex min-h-[46px] justify-start"></div><div class="mt-3 w-full empty:hidden"><div class="text-center"></div></div></div></div></section><div class="contents"></div></div></div><div aria-hidden="true" class="pointer-events-none -mt-px h-px translate-y-[calc(var(--scroll-root-safe-area-inset-bottom)-14*var(--spacing))]"></div>', 4, '1778344920.png', '2026-05-09', '2026-05-09 11:12:00', '2026-05-09 11:12:00');

